#define NorthlightRegionalFog FogOld
#include "fog_reference/regional-old.h"
#undef NorthlightRegionalFog
#include "regional_fog.h"
#include <cassert>
#include <random>
template<class R,class T> R region(){R r;for(int i=0;i<9;++i){T t;t.x=31+i%3;t.y=31+i/3;for(int j=0;j<256;++j)t.zones[j]=(j%6==0?10:j%6==1?33:j%6==2?12:j%6==3?440:j%6==4?1519:0);r.tiles.push_back(t);}return r;}
int main(){auto old=region<FogOld::Region,FogOld::Tile>();auto now=region<NorthlightRegionalFog::Region,NorthlightRegionalFog::Tile>();NorthlightGI::WorldScene s;NorthlightGI::WorldMaterial m;m.terrain=true;s.materials.push_back(m);for(auto v:std::array<std::array<float,2>,4>{{{{-100500,-100500}},{{100500,-100500}},{{100500,100500}},{{-100500,100500}}}})s.vertices.push_back({{v[0],v[1],100},{0,0,1},0,0});s.triangles.push_back({0,1,2,0});s.triangles.push_back({0,2,3,0});m.terrain=false;s.materials.push_back(m);s.triangles.push_back({99999,99999,99999,1});s.triangles.push_back({99999,1,2,0});s.triangles.push_back({1,2,99999,0});s.triangles.push_back({1,2,3,99999});s.vertices.push_back({{NAN,0,0},{0,0,1},0,0});s.vertices.push_back({{INFINITY,0,0},{0,0,1},0,0});s.triangles.push_back({4,1,2,0});s.triangles.push_back({0,5,2,0});s.triangles.push_back({1,1,1,0});std::mt19937 gen(4829);for(int i=0;i<200;++i){float x=i<10?float(i*22222-100000):float(int(gen()%1001)-500),y=i<10?float(100000-i*22222):float(int(gen()%1001)-500);auto a=FogOld::buildField(s,old,x,y);auto b=NorthlightRegionalFog::buildField(s,now,x,y);assert(!memcmp(a.texels.data(),b.texels.data(),sizeof(a.texels)));assert(!memcmp(a.lush.data(),b.lush.data(),sizeof(a.lush)));assert(a.groundCells==b.groundCells&&a.fogCells==b.fogCells&&a.airCells==b.airCells&&a.indoorCells==b.indoorCells&&a.citySurfaceCells==b.citySurfaceCells);}}
